<template><article class="card repair-card" @click="$emit('open',repair.id)"><div><h3>{{repair.title}}</h3><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · {{new Date(repair.created_at).toLocaleString()}}</small><div class="repair-appointment"><el-icon><Clock/></el-icon><span>{{appointmentText}}</span><el-tag v-if="repair.handler" size="small" type="info" effect="plain">处理人：{{repair.handler.nickname}}</el-tag><el-tag v-else size="small" type="warning" effect="plain">未分派</el-tag></div></div><RepairStatusBadge :status="repair.status"/></article></template><script setup lang="ts">import{computed}from'vue';import{Clock}from'@element-plus/icons-vue';import type{Repair}from'../../types';import{repairSlotText}from'../../constants/repair';import RepairStatusBadge from'./RepairStatusBadge.vue';const p=defineProps<{repair:Repair}>();defineEmits<{open:[id:number]}>();const appointmentText=computed(()=>p.repair.appointment_date?`预约：${p.repair.appointment_date} ${repairSlotText[p.repair.appointment_slot]}`:'暂未预约');</script>
